// Parse the current production JSON (kept as the template for the new one)
const buf = await this.helpers.getBinaryDataBuffer(0, 'json_vigente');
const current = JSON.parse(buf.toString('utf8'));
return [{ json: { current }, binary: $input.first().binary }];

// Normalize the regulator's table: fill down merged cells, keep numeric rows, list headers and target keys
const rows = [];
let lastTariff = null;
const valueHeaders = new Set();
$input.all().forEach((item, idx) => {
  const r = item.json;
  const tariff = (r['Tarifa'] ?? '').toString().trim() || lastTariff;
  lastTariff = tariff;
  const values = {};
  for (const [k, v] of Object.entries(r)) {
    if (['Tarifa', 'Concepto', 'Unidad'].includes(k)) continue;
    if (v === '' || v === null || v === undefined) continue;
    const num = typeof v === 'number' ? v : Number(String(v).replace(/\./g, '').replace(',', '.'));
    if (Number.isFinite(num)) { values[k] = num; valueHeaders.add(k); }
  }
  if (r['Concepto'] && Object.keys(values).length) {
    rows.push({ row_id: rows.length + 1, tariff_label: tariff, concept: r['Concepto'], unit: r['Unidad'] ?? '', values });
  }
});

const current = $('Read current JSON').first().json.current;
const targets = Object.entries(current.tariffs).map(([key, charges]) => ({
  tariff_key: key,
  fields: Object.fromEntries(Object.entries(charges).map(([f, lv]) => [f, Object.keys(lv)])),
}));

return [{ json: {
  rows,
  value_headers: [...valueHeaders],
  targets,
  prompt_rows: rows.map(r => `${r.row_id}. ${r.tariff_label} | ${r.concept} | ${r.unit}`).join('\n'),
} }];

