// Apply the mapping with code: build the new JSON, compare against the current one, flag anomalies
const MAX_CHANGE_PCT = 40;  // variations above this need a human check
const { rows } = $('Normalize table').first().json;
const current = $('Read current JSON').first().json.current;
const form = $('Upload files').first().json;
const map = $input.first().json.output;

const next = JSON.parse(JSON.stringify(current));
next.resolution = form.resolucion;
next.valid_from = form.vigencia;

const levelOf = Object.fromEntries(map.column_mappings.map(c => [c.header, c.level_key]));
const rowMap = Object.fromEntries(map.row_mappings.map(r => [r.row_id, r]));
const issues = [];
const changes = [];
const updated = new Set();

for (const row of rows) {
  const m = rowMap[row.row_id];
  if (!m?.tariff_key || !m?.field || !next.tariffs[m.tariff_key]?.[m.field]) {
    issues.push(`Fila sin destino: "${row.tariff_label} | ${row.concept}"`);
    continue;
  }
  for (const [header, value] of Object.entries(row.values)) {
    const level = levelOf[header];
    if (!level || !(level in next.tariffs[m.tariff_key][m.field])) continue;
    const path = `${m.tariff_key}.${m.field}.${level}`;
    const old = current.tariffs[m.tariff_key][m.field][level];
    const pct = old ? ((value - old) / old) * 100 : null;
    next.tariffs[m.tariff_key][m.field][level] = value;
    updated.add(path);
    changes.push({ path, old, new: value, change_pct: pct === null ? null : Math.round(pct * 100) / 100 });
    if (value <= 0) issues.push(`${path}: valor no positivo (${value})`);
    if (pct !== null && Math.abs(pct) > MAX_CHANGE_PCT) issues.push(`${path}: variación de ${pct.toFixed(1)}% (${old} → ${value})`);
  }
}

// Every key of the current config must receive a new value
for (const [t, charges] of Object.entries(current.tariffs))
  for (const [f, levels] of Object.entries(charges))
    for (const l of Object.keys(levels))
      if (!updated.has(`${t}.${f}.${l}`)) issues.push(`${t}.${f}.${l}: no se encontró en el Excel (quedó el valor anterior)`);

const avg = changes.length ? changes.reduce((s, c) => s + (c.change_pct ?? 0), 0) / changes.length : 0;
const fileName = `cuadro_tarifario_${String(form.resolucion).replace(/\W+/g, '_')}.json`;
const table = changes.map(c => `<tr><td>${c.path}</td><td>${c.old}</td><td>${c.new}</td><td>${c.change_pct}%</td></tr>`).join('');
const report_html = `<h3>${issues.length ? '⚠️ Revisar antes de publicar' : '✅ Listo para publicar'}</h3>
<p>${changes.length} valores actualizados · variación promedio ${avg.toFixed(2)}%</p>
${issues.length ? '<ul>' + issues.map(i => `<li>${i}</li>`).join('') + '</ul>' : ''}
<table border="1" cellpadding="4"><tr><th>Clave</th><th>Anterior</th><th>Nuevo</th><th>Var.</th></tr>${table}</table>`;

return [{ json: { ok: issues.length === 0, issues, changes, avg_change_pct: Math.round(avg * 100) / 100, file_name: fileName, report_html, new_config: next } }];
